{
  "name": "ll_build_data_packet",
  "confidence": "medium",
  "docstring": "Prepares a BLE link-layer data PDU by copying descriptor indices, initializing associated packet buffers, and selecting per-descriptor TX power before checking pending TX work.",
  "subsystem": "ble",
  "var_renames": {
    "a1": "ll_ctx",
    "a2": "unused_param",
    "v5": "idx_source_cur",
    "v7": "idx_source_end",
    "v8": "pkt_frame_dest",
    "v9": "source_idx",
    "v11": "tx_desc_count",
    "v14": "entry_pkt_buf",
    "v18": "desc_idx",
    "v20": "pkt_idx",
    "v21": "tx_power"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "per-entry packet buffer/descriptor pointer, used by rx_init_packet_buf"
    },
    {
      "offset": 10,
      "meaning": "per-entry 16-bit source field copied into the data packet template"
    },
    {
      "offset": 14,
      "meaning": "per-entry active/initialized byte flag"
    },
    {
      "offset": 124,
      "meaning": "pending packet buffer handle initialized by rx_init_packet_buf and tested/cleared"
    },
    {
      "offset": 126,
      "meaning": "related LL/RX state cleared when the pending buffer is processed"
    },
    {
      "offset": 136,
      "meaning": "start of 8-entry u16 table of descriptor/source indices"
    },
    {
      "offset": 144,
      "meaning": "end marker for the 8-entry index table; also updated when offset 146 is nonzero"
    },
    {
      "offset": 184,
      "meaning": "number of active LL TX data descriptors"
    },
    {
      "offset": 190,
      "meaning": "pending TX descriptor/event index, with 0xFFFF as the no-pending sentinel"
    }
  ]
}
